-- =============================================================================
-- University of Nigeria, Nsukka — Faculty of Social Sciences — Psychology
-- Course outlines transcribed from the Faculty of Social Sciences course
-- handbook (scanned copy), covering the Four-Year B.Sc Degree Programme in
-- Psychology: all four years, both semesters, including required ancillary,
-- general-studies and elective courses.
-- =============================================================================
-- Run in the Supabase SQL Editor. Safe to run more than once: existing rows
-- for this department are removed first, so it updates rather than duplicates.
--
-- SEMESTERS: the handbook explicitly labels every course "FIRST SEMESTER" or
-- "SECOND SEMESTER" in its programme-structure tables, so those stated values
-- are used directly — no guessing was needed here.
--
-- ANCILLARY/GSP/ELECTIVE COURSES FROM OTHER DEPARTMENTS: courses such as
-- SOC 101/102, PSC 101/102, GSP 1xx/2xx, BIO 151/152, MAN 141, PHIL 101,
-- VTE 133, COS 101/304 and CED 341/342 appear in the Psychology timetable
-- but their own descriptions are not printed in the Psychology section of
-- this document, so they carry real code/title/units only, description left
-- blank pending a verified source elsewhere in this app.
-- =============================================================================

delete from public.course_outlines
 where institution = 'University of Nigeria, Nsukka'
   and department = 'Psychology';

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name)
values
  ('PSY 101', 'Introduction to Psychology I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '100 Level', 'first', 3, 'The Science of Psychology: History of Psychology Research methods in Psychology Fields of Psychology and other Disciplines. Biological Basis of Human Development.', '["The Science of Psychology: History of Psychology", "Research methods in Psychology", "Fields of Psychology and other Disciplines", "Biological Basis of Human Development"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 103', 'Psychology of Learning', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '100 Level', 'first', 2, 'Definition of learning. Types of learning: classical conditioning, operant conditioning, social learning, concept learning, etc. Measurement of learning and their uses. Complex learning: Learning set or learning-to-learn; insight. Brain substrates of learning; memory and artificial intelligence. Practicals.', '["Definition of learning. Types of learning: classical conditioning, operant conditioning, social learning, concept learning, etc", "Measurement of learning and their uses", "Complex learning: Learning set or learning-to-learn; insight", "Brain substrates of learning; memory and artificial intelligence. Practicals"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 111', 'Quantitative Methods in Psychology I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '100 Level', 'first', 2, 'The need to study quantitative methods in Psychology. Types of quantitative methods and brief description of each. Frequency distributions and their uses. Measures of central tendency and measures of dispersion. Practical exercises and assignments will feature throughout.', '["The need to study quantitative methods in Psychology", "Types of quantitative methods and brief description of each", "Frequency distributions and their uses", "Measures of central tendency and measures of dispersion", "Practical exercises and assignments will feature throughout"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 121', 'Basic Concepts in Experimental Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '100 Level', 'first', 2, 'The basic nature of research-variable, observation, hypothesis, theory, procedure, selection, assignment, population, subjects, materials/equipment, sampling, randomization etc. Experimental control variability, confounding, interaction, etc. Design of experiments: One-way designs, factorial designs, between versus within-subjects designs, correlation designs etc. Statistical analysis - descriptive statistics, inferential statistics, research report.', '["The basic nature of research-variable, observation, hypothesis, theory, procedure, selection, assignment, population, subjects, materials/equipment, sampling, randomization etc", "Experimental control variability, confounding, interaction, etc", "Design of experiments: One-way designs, factorial designs, between versus within-subjects designs, correlation designs etc", "Statistical analysis - descriptive statistics, inferential statistics, research report"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 102', 'Introduction to Psychology II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '100 Level', 'second', 3, 'Sensation and Perception. Mind versus body, learning and memory. Motivation and Emotion. Personality. Assessing individual Differences. Problems of adjustment in behaviour.', '["Sensation and Perception. Mind versus body, learning and memory", "Motivation and Emotion", "Personality. Assessing individual Differences", "Problems of adjustment in behaviour"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 112', 'Quantitative Methods in Psychology II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '100 Level', 'second', 2, 'Correlation and correlation coefficients. The t-test. The F-test. Introduction to Analysis of Variance (ANOVA). Non-parametric methods and their uses in psychology. Practical exercises and assignments will be a regular feature.', '["Correlation and correlation coefficients", "The t-test. The F-test", "Introduction to Analysis of Variance (ANOVA)", "Non-parametric methods and their uses in psychology", "Practical exercises and assignments will be a regular feature"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 132', 'Psychobiology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '100 Level', 'second', 2, 'The sensory system: a detailed examination of the physiology of the chemical, visual, auditory and somatic senses as they relate to psychological processes. Motor control and sensory motor integration: focus on the response systems.', '["The sensory system: a detailed examination of the physiology of the chemical, visual, auditory and somatic senses as they relate to psychological processes", "Motor control and sensory motor integration: focus on the response systems"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 142', 'Ethics in Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '100 Level', 'second', 2, 'Morality and ethical guidelines in the treatment of human participants and non-human subjects in psychological research and practice. Concept and consequences of torture, cruel and inhuman or degrading treatment. Authority, law enforcement and redress of unethical behaviour.', '["Morality and ethical guidelines in the treatment of human participants and non-human subjects in psychological research and practice", "Concept and consequences of torture, cruel and inhuman or degrading treatment", "Authority, law enforcement and redress of unethical behaviour"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 221', 'General Experimental Psychology I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '200 Level', 'first', 2, 'Historical introduction to experimental psychology. Steps and issues involved in designing an experiment as well as hints on running experiments will be discussed. How to write up an experiment will also be covered. Practicals.', '["Historical introduction to experimental psychology", "Steps and issues involved in designing an experiment as well as hints on running experiments will be discussed", "How to write up an experiment will also be covered. Practicals"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 231', 'Physiological Psychology I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '200 Level', 'first', 2, 'Meaning and scope. The Chemical senses. The Visual system and Visual perception. The Auditory system. The somatic senses. Motor functions. Emotion.', '["Meaning and scope", "The Chemical senses", "The Visual system and Visual perception", "The Auditory system", "The somatic senses. Motor functions. Emotion"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 241', 'Introduction to Social Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '200 Level', 'first', 2, 'Definition of social psychology. Psychology as a science. Social psychological assumptions. Social psychology and other social sciences. Socialization as the root of social behaviour. Attitude: definition, formation, functions and components.', '["Definition of social psychology. Psychology as a science. Social psychological assumptions", "Social psychology and other social sciences", "Socialization as the root of social behaviour", "Attitude: definition, formation, functions and components"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 251', 'Developmental Psychology I: Childhood and Adolescence', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '200 Level', 'first', 2, 'This course offers topics on human growth and development from conception to adolescence. Areas to be covered include history and theories of child development, determinants of development, conception and the mechanism of heredity, cognitive, language, and personality development in infancy, early childhood and later childhood; physical and physiological changes at puberty; the meaning of identity in adolescence and adolescent behavioural problems.', '["This course offers topics on human growth and development from conception to adolescence", "Areas to be covered include history and theories of child development, determinants of development, conception and the mechanism of heredity", "Cognitive, language, and personality development in infancy, early childhood and later childhood", "Physical and physiological changes at puberty; the meaning of identity in adolescence and adolescent behavioural problems"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 261', 'Psychology of Personality', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '200 Level', 'first', 2, 'The problem of personality definitions. Personality types, personality theories; psychometric and trait approach to personality, psychoanalytic approach to personality, social learning approach to personality, humanistic approach to personality. Critical implications.', '["The problem of personality definitions", "Personality types, personality theories; psychometric and trait approach to personality", "Psychoanalytic approach to personality, social learning approach to personality, humanistic approach to personality", "Critical implications"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 202', 'Psychological Measurement', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '200 Level', 'second', 2, 'Historical development and concept of psychological measurement. Theories of psychological measurement (including classical test theory, item response theory, and Validity. Cultural issues (linguistic, religious) in psychological measurement. Method biases in psychological measurement: response style, same method errors, etc. Measurement models underlying psychological scales (including tau-equivalent models, congeneric model), and their implications for statistical analysis. Estimation of validity and reliability indices for psychological measures.', '["Historical development and concept of psychological measurement", "Theories of psychological measurement (including classical test theory, item response theory), and Validity", "Cultural issues (linguistic, religious) in psychological measurement", "Method biases in psychological measurement: response style, same method errors, etc", "Measurement models underlying psychological scales (including tau-equivalent models, congeneric model), and their implications for statistical analysis", "Estimation of validity and reliability indices for psychological measures"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 222', 'General Experimental Psychology II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '200 Level', 'second', 2, 'Demonstrations of a number of experiments in class. Thereafter emphasis will be placed on the students'' designing, undertaking, analysing and reporting their own experiments as practicals. Review of analysis of variance (ANOVA) technique will be discussed.', '["Demonstrations of a number of experiments in class", "Thereafter emphasis will be placed on the students'' designing, undertaking, analysing and reporting their own experiments as practicals", "Review of analysis of variance (ANOVA) technique will be discussed"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 232', 'Physiological Psychology II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '200 Level', 'second', 2, 'Physiological bases of sleep, arousal and activity. Hunger and Thirst, Sexual Behaviour. Instinctive Conditioning. Conditioning and decision making. Learning disorders. Psychochemistry.', '["Physiological bases of sleep, arousal and activity", "Hunger and Thirst, Sexual Behaviour", "Instinctive Conditioning. Conditioning and decision making", "Learning disorders. Psychochemistry"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 234', 'Sensation and Perception', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '200 Level', 'second', 2, 'Physical bases of sensation and the distinction between sensation and perception. Emphasis on human visual, chemical and auditory senses. Approaches to study of perception. Attention processes. Organizational processes in perception. Identification and Recognition processes.', '["Physical bases of sensation and the distinction between sensation and perception", "Emphasis on human visual, chemical and auditory senses", "Approaches to study of perception. Attention processes", "Organizational processes in perception. Identification and Recognition processes"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 242', 'Psychology of Ethnicity and Ethnic Groups', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '200 Level', 'second', 2, 'Basis for ethnicity: positive and negative aspects of ethnicity; methods for reducing adverse effects of ethnicity as they apply to ethnic group relations in Nigeria.', '["Basis for ethnicity: positive and negative aspects of ethnicity", "Methods for reducing adverse effects of ethnicity as they apply to ethnic group relations in Nigeria"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 244', 'Psychology of Gender Issues', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '200 Level', 'second', 2, 'Historical developments in gender relations. Socio-cultural myths/ideology that reinforce gender discrimination and abuse. Sex-role conditioning. Theories of gender inequality. The roles of religion, culture, literature, mass media in maintaining the status quo (gender inequality). An alternative paradigm - the issue of androgyny; the archetypes (animan and animus) and complementarity. Contemporary issues in gender studies.', '["Historical developments in gender relations. Socio-cultural myths/ideology that reinforce gender discrimination and abuse", "Sex-role conditioning. Theories of gender inequality", "The roles of religion, culture, literature, mass media in maintaining the status quo (gender inequality)", "An alternative paradigm - the issue of androgyny; the archetypes (animan and animus) and complementarity", "Contemporary issues in gender studies"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 252', 'Developmental Psychology II: Adulthood and Ageing', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '200 Level', 'second', 2, 'This course deals with the changes and adjustment demands from the age of maturing till the late life cycle ends in death. Topics include theory and research in adult development, early adulthood, mid-life transition, later adulthood; biological, intellectual and personality inputs of ageing, and finally dying and bereavements.', '["This course deals with the changes and adjustment demands from the age of maturing till the late life cycle ends in death", "Topics include theory and research in adult development, early adulthood, mid-life transition, later adulthood", "Biological, intellectual and personality inputs of ageing, and finally dying and bereavements"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 254', 'Psychology of Child Labour, Abuse and Trafficking', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '200 Level', 'second', 2, 'Theoretical and conceptual issues in child abuse. Categories of child abuse. Child trafficking and the effects of child labour. The nature of child abuse. Societal responses to child abuse issues. Combating child abuse - legal and non-legal methods. Research methods in child abuse.', '["Theoretical and conceptual issues in child abuse. Categories of child abuse", "Child trafficking and the effects of child labour. The nature of child abuse", "Societal responses to child abuse issues. Combating child abuse - legal and non-legal methods", "Research methods in child abuse"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 311', 'Statistical Methods in Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'first', 2, 'Complex factorial designs. Randomized block designs, repeated measures design, and trend analysis. Linear regression and correlation. Advanced statistical methods as applied to psychology, including parametric and non-parametric tests of significance, analysis of covariance, multiple regression, structural equation modelling and related methods. Introduction to factor analysis.', '["Complex factorial designs. Randomized block designs, repeated measures design, and trend analysis", "Linear regression and correlation", "Advanced statistical methods as applied to psychology, including parametric and non-parametric tests of significance, analysis of covariance, multiple regression, structural equation modelling and related methods", "Introduction to factor analysis"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 331', 'Motivation and Emotion', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'first', 2, 'Phenomena of motivation. Dynamics of motivation, development of motives, hunger, motivation, sexual motivation, motivation for personal Achievement. Emotions. Theories of Emotion. Functions of Emotion.', '["Phenomena of motivation. Dynamics of motivation, development of motives, hunger, motivation, sexual motivation", "Motivation for personal Achievement", "Emotions. Theories of Emotion. Functions of Emotion"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 341', 'Industrial/Occupational Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'first', 2, 'The scope and history of industrial/occupational psychology. The concept of work, individual differences and its industrial/occupational implications, vocational choice and vocational guidance, ergonomics, industrial accidents and safety.', '["The scope and history of industrial/occupational psychology", "The concept of work, individual differences and its industrial/occupational implications", "Vocational choice and vocational guidance, ergonomics, industrial accidents and safety"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 343', 'Personnel Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'first', 2, 'Development and evaluation of selection techniques, job analysis and placement; evaluating the selection process, training of personnel, analysis of criteria, job performance and evaluation. Common factors in the selection and training of industrial and paraprofessional personnel. The role of the interview. Problems of selection in developing countries.', '["Development and evaluation of selection techniques, job analysis and placement; evaluating the selection process", "Training of personnel, analysis of criteria, job performance and evaluation", "Common factors in the selection and training of industrial and paraprofessional personnel", "The role of the interview. Problems of selection in developing countries"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 345', 'Political Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'first', 2, 'Personality, attitude and social perception as basic psychological constructs which influence political behaviour; major orienting approaches in the formation and expression of political beliefs and activities: socialization, alienation, Leadership, conflict, violence, revolution, war; Africa regional politics and international relations.', '["Personality, attitude and social perception as basic psychological constructs which influence political behaviour", "Major orienting approaches in the formation and expression of political beliefs and activities: socialization, alienation", "Leadership, conflict, violence, revolution, war", "Africa regional politics and international relations"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 347', 'Cross-cultural Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'first', 2, 'The nature-nurture issues and the rise of cross-cultural psychology. The need for cross-cultural psychology. Comparative studies of the influences of culture on perception, thinking and socio-cultural developments. Methodological problems.', '["The nature-nurture issues and the rise of cross-cultural psychology", "The need for cross-cultural psychology", "Comparative studies of the influences of culture on perception, thinking and socio-cultural developments", "Methodological problems"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 351', 'Abnormal/Clinical Psychology I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'first', 2, 'Introduction: Historical and Scientific Consideration, Current theoretical perspectives, classification, Diagnosis and Treatment plans; Clinical assessment, Clinical Research Methods; Anxiety Disorders; Somatoform and Dissociative Disorders; Psycho physiological Disorders, Mood Disorders; Schizophrenia. Practicals and field training.', '["Introduction: Historical and Scientific Consideration, Current theoretical perspectives, classification, Diagnosis and Treatment plans", "Clinical assessment, Clinical Research Methods", "Anxiety Disorders; Somatoform and Dissociative Disorders; Psycho physiological Disorders, Mood Disorders; Schizophrenia", "Practicals and field training"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 361', 'Counselling Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'first', 2, 'The concept of counselling psychology: origin and development, counselling relationship within the helping professions; individual and group counselling in various settings (e.g. vocational, educational, family, social, etc). Counselling programmes and services.', '["The concept of counselling psychology: origin and development, counselling relationship within the helping professions", "Individual and group counselling in various settings (e.g. vocational, educational, family, social, etc)", "Counselling programmes and services"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 371', 'Theories and Systems', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'first', 2, 'Philosophical antecedents of modern psychology. The rise of the research spirit. Beginnings of experimentation - Pavlov, Webber, Fechner, Mueller, etc. physiological psychology - functionalism, behaviourism, Gestalt psychology. Freud and Post/Neo Freudians. Humanistic psychology, Phenomenological and existential approaches. African orientations. A possible synthesis.', '["Philosophical antecedents of modern psychology. The rise of the research spirit", "Beginnings of experimentation - Pavlov, Webber, Fechner, Mueller, etc. physiological psychology - functionalism, behaviourism, Gestalt psychology", "Freud and Post/Neo Freudians. Humanistic psychology, Phenomenological and existential approaches", "African orientations. A possible synthesis"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 381', 'Environmental Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'first', 2, 'Definition and Dimensions of the environment. Major assumptions about the environment. Theories of environmental psychology; cognition, Gestalt. Topological or field theory systems. Problem of cities. Crowding and behaviour. Problem of conservation of natural resources. Environmental pollution. Methods of environmental assessment. Critical issues of man as part of an ecological system.', '["Definition and Dimensions of the environment. Major assumptions about the environment", "Theories of environmental psychology; cognition, Gestalt. Topological or field theory systems", "Problem of cities. Crowding and behaviour", "Problem of conservation of natural resources. Environmental pollution", "Methods of environmental assessment. Critical issues of man as part of an ecological system"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 302', 'Cognitive Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'second', 2, 'Emphasis will be placed on cognitive processes such as pattern recognition, attention, memory and imagery, language, thinking concept formation, problem solving and artificial intelligence. Computer simulation. The influence of culture on cognition will be discussed.', '["Emphasis will be placed on cognitive processes such as pattern recognition, attention, memory and imagery", "Language, thinking concept formation, problem solving and artificial intelligence", "Computer simulation. The influence of culture on cognition will be discussed"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 312', 'Research Methods in Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'second', 2, 'The nature and scope of research - research mentality (qualities of good researcher); planning of research. Types of research: experimental versus non-experimental research. Ethical issues in psychological research. Writing of research report.', '["The nature and scope of research - research mentality (qualities of good researcher); planning of research", "Types of research: experimental versus non-experimental research", "Ethical issues in psychological research", "Writing of research report"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 342', 'Advanced Social Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'second', 2, 'Theories and techniques of social change. Attitude measurement. Methods of research in social psychology. Leadership and leadership effectiveness. Achievement motivation. Obedience and compliance.', '["Theories and techniques of social change. Attitude measurement", "Methods of research in social psychology", "Leadership and leadership effectiveness. Achievement motivation", "Obedience and compliance"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 352', 'Abnormal/Clinical Psychology II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'second', 2, 'Substance-related disorders, Eating disorders and impulse control Disorders; Personality Disorder, cognitive Disorder and Gender Identity Disorder; Disorder of Childhood, Aging and Psychological Disorders; issues in Psychological Intervention, Ethical and Legal Issues. African orientations to causation and treatment. Practicals and field training.', '["Substance-related disorders, Eating disorders and impulse control Disorders", "Personality Disorder, cognitive Disorder and Gender Identity Disorder", "Disorder of Childhood, Aging and Psychological Disorders; issues in Psychological Intervention, Ethical and Legal Issues", "African orientations to causation and treatment. Practicals and field training"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 354', 'Psychology of Substance Abuse', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'second', 2, 'The nature and dynamics of substance abuse. Basic aspects of pharmacology of psychotropic drugs. Drugs of addiction and abuse-alcohol. The opiates, synthetic analgesics, cannabis (marijuana), psycho-stimulants (amphetamines), hallucinogens, tobacco, etc. stages of alcohol dependence, diagnosis and management of drug dependence Rehabilitation.', '["The nature and dynamics of substance abuse. Basic aspects of pharmacology of psychotropic drugs", "Drugs of addiction and abuse-alcohol. The opiates, synthetic analgesics, cannabis (marijuana), psycho-stimulants (amphetamines), hallucinogens, tobacco, etc", "Stages of alcohol dependence, diagnosis and management of drug dependence Rehabilitation"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 356', 'Psychology of Mental Challenge', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'second', 2, 'Brief History. Causes (aetiology). Classification. Degrees or levels of mental challenge. Diagnoses. The mentally challenged in the family, and society. Societal attitudes towards the mentally challenged. Learning and education of the mentally challenged. Treatment, management, training, rehabilitation and prevention. The Nigeria perspective in mental challenge. Conceptions and misconceptions about mental challenge and their cultural relativity. Practicality in the form of case studies.', '["Brief History. Causes (aetiology). Classification. Degrees or levels of mental challenge. Diagnoses", "The mentally challenged in the family, and society. Societal attitudes towards the mentally challenged", "Learning and education of the mentally challenged", "Treatment, management, training, rehabilitation and prevention", "The Nigeria perspective in mental challenge. Conceptions and misconceptions about mental challenge and their cultural relativity"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 362', 'Personality Assessment', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'second', 2, 'Classification of traits. Measurement of personality traits. Idiographic and nomothetic theories of personality. Self inventories. Observational methods. Projective techniques. Physiological measures. Critical issues and problems.', '["Classification of traits. Measurement of personality traits", "Idiographic and nomothetic theories of personality", "Self inventories. Observational methods. Projective techniques", "Physiological measures. Critical issues and problems"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 384', 'Psychology of Social Change', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '300 Level', 'second', 2, 'This course examines the social and psychological factors in social change, the dynamics of technological impact on culture and value system. Policy implications of social change.', '["This course examines the social and psychological factors in social change, the dynamics of technological impact on culture and value system", "Policy implications of social change"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 401', 'Computer Applications in Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'first', 2, 'An overview of the uses of computer. Computer-mediated assessment methods. Data analysis with computers - emphasis on the use of statistical application packages such as SPSS and interpretation of computer-generated results. The impact of computer technology on humans. New developments in computer applications in psychology. The use of internet for research communication and psychological research. Practicals.', '["An overview of the uses of computer. Computer-mediated assessment methods", "Data analysis with computers - emphasis on the use of statistical application packages such as SPSS and interpretation of computer-generated results", "The impact of computer technology on humans", "New developments in computer applications in psychology. The use of internet for research communication and psychological research. Practicals"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 431', 'Advanced Psychobiology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'first', 2, 'Brain chemistry, Brain Disorders and psychopathology-examines the neurochemical factors in brain disorders as they relate to mental disorders, schizophrenia, depression and anxiety. Emphasis on current empirical evidence.', '["Brain chemistry, Brain Disorders and psychopathology-examines the neurochemical factors in brain disorders as they relate to mental disorders, schizophrenia, depression and anxiety", "Emphasis on current empirical evidence"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 441', 'Social Perception', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'first', 2, 'Perception and social perception. Differences in social perception inference processes and forming impressions of others. Perception of emotion. Theoretical approaches to attribution. Attribution rules and attribution biases. Self perception. Implications of social perception and attribution processes for interpersonal and intergroup relations.', '["Perception and social perception. Differences in social perception inference processes and forming impressions of others", "Perception of emotion. Theoretical approaches to attribution", "Attribution rules and attribution biases. Self perception", "Implications of social perception and attribution processes for interpersonal and intergroup relations"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 442', 'Psychology of Union Management Relations', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'first', 2, 'The meaning and scope of industrial relations as a discipline. The role of perception and motivation in the understanding of union management relations. The socio-psychological significance of and determinants of pay. The role of psychology in industrial bargaining, the role of psychology in industrial disputes and its settlement.', '["The meaning and scope of industrial relations as a discipline", "The role of perception and motivation in the understanding of union management relations", "The socio-psychological significance of and determinants of pay", "The role of psychology in industrial bargaining, the role of psychology in industrial disputes and its settlement"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 443', 'Psychology of Vocational Behaviour', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'first', 2, 'Theoretical and empirical analysis of factors underlying choice of vocation, work organizations and careers. Topics include psychological determinants of vocational choice. Dynamics of job determinants of vocational choice, dynamics of job entry, vocational success, career leaders and effects of technological advance on jobs and workers.', '["Theoretical and empirical analysis of factors underlying choice of vocation, work organizations and careers", "Topics include psychological determinants of vocational choice", "Dynamics of job determinants of vocational choice, dynamics of job entry, vocational success, career leaders and effects of technological advance on jobs and workers"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 445', 'Consumer Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'first', 2, 'The course will focus on the human as a consumer of goods and services, the choices he makes and factors that determine the choice. Topics will cover such areas as the exchange theory, and social and individual influences on consumer behaviour, the defects of advertisement, brand and product image, and consumer preference, effect of economic conditions on consumer behaviour, market research and its use.', '["The course will focus on the human as a consumer of goods and services, the choices he makes and factors that determine the choice", "Topics will cover such areas as the exchange theory, and social and individual influences on consumer behaviour", "The defects of advertisement, brand and product image, and consumer preference", "Effect of economic conditions on consumer behaviour, market research and its use"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 447', 'Organizational Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'first', 2, 'Man within a wider organizational context. The course will cover issues such as the concept of power and authority, formal and informal groups, group conflicts and their resolution, the nature of industrial leadership, motivation, human problems of technological change, communication.', '["Man within a wider organizational context", "The course will cover issues such as the concept of power and authority, formal and informal groups, group conflicts and their resolution", "The nature of industrial leadership, motivation, human problems of technological change, communication"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 451', 'Health Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'first', 2, 'Concept and history of health psychology. Stress, stressors, stress reaction, health and coping. Biopsychosocial model of health, health processes. Health care systems. Health policies - national and International.', '["Concept and history of health psychology", "Stress, stressors, stress reaction, health and coping", "Biopsychosocial model of health, health processes. Health care systems", "Health policies - national and International"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 453', 'Behaviour Modification', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'first', 2, 'Exploration of rationale underlying behaviour change, especially in human beings. The theoretical bases of psychological therapies - psychoanalytic, client-centred, gestalt, behavioural, cognitive, and couples/family therapies; psychotherapy integration. This will be followed by practical training in the use of psychological techniques in bringing about behaviour change.', '["Exploration of rationale underlying behaviour change, especially in human beings", "The theoretical bases of psychological therapies - psychoanalytic, client-centred, gestalt, behavioural, cognitive, and couples/family therapies; psychotherapy integration", "This will be followed by practical training in the use of psychological techniques in bringing about behaviour change"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 461', 'Psychological Testing and Test Construction', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'first', 2, 'Theories and foundations of the psychometric tradition. Origins of the testing movement. The nature of mental abilities and traits. Basic attributes of psychological tests - validity and predictive utility. Statistical foundations of psychometrics. Techniques of test construction - determining domain, item selection and analysis, item validity, difficulty level. Meaningful test profile, item analysis and interpretation of tests. Practical work.', '["Theories and foundations of the psychometric tradition. Origins of the testing movement", "The nature of mental abilities and traits. Basic attributes of psychological tests - validity and predictive utility", "Statistical foundations of psychometrics. Techniques of test construction - determining domain, item selection and analysis, item validity, difficulty level", "Meaningful test profile, item analysis and interpretation of tests. Practical work"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 432', 'Psychopharmacology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'second', 2, 'Introduction to psychopharmacology. Examines attempts to alter behaviour through the use of drugs, e.g. anxiolytics, antidepressants, sedatives. The role of psychotomimetic drugs and other drugs of addiction in the alteration of behaviour.', '["Introduction to psychopharmacology", "Examines attempts to alter behaviour through the use of drugs, e.g. anxiolytics, antidepressants, sedatives", "The role of psychotomimetic drugs and other drugs of addiction in the alteration of behaviour"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 452', 'Forensic Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'second', 2, 'The concept of forensic psychology. Issues in identification parade. Reliability of eye-witness testimony. Construction of the personality profile and confession of the offender. Social psychology in the courtroom. The mental health status of the offender.', '["The concept of forensic psychology. Issues in identification parade", "Reliability of eye-witness testimony", "Construction of the personality profile and confession of the offender", "Social psychology in the courtroom. The mental health status of the offender"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 454', 'Practicum in Psychotherapy', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'second', 2, 'The course will provide the students an opportunity to handle real clinical cases under strict supervised conditions. The students will be exposed to the application of advanced techniques of behaviour change in the management of cases.', '["The course will provide the students an opportunity to handle real clinical cases under strict supervised conditions", "The students will be exposed to the application of advanced techniques of behaviour change in the management of cases"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 462', 'Psychological Testing and Assessment', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'second', 2, 'The intake interview - industrial/clinical. Intellectual assessment, use of the Wechsler series, Stanford-Binet, DAP, Bender gestalt, Porteus Maze tests etc. Personality inventory, MMPI, TSES, MMPI. Projective techniques: Rorschach inkblot test, incomplete sentences, etc. Psychological report.', '["The intake interview - industrial/clinical", "Intellectual assessment, use of the Wechsler series, Stanford-Binet, DAP, Bender gestalt, Porteus Maze tests etc", "Personality inventory, MMPI, TSES", "Projective techniques: Rorschach inkblot test, incomplete sentences, etc. Psychological report"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 472', 'Current Issues in Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'second', 2, 'Basic issues - persistence of the mind-body problem, socio-economic developmental questions peculiar to African societies, etc; applied issues: social political leadership and leadership behaviour, allegation problems in marriage and family life, religion and the problems of religious dogmatism in Nigeria, environmental pollution, etc.', '["Basic issues - persistence of the mind-body problem, socio-economic developmental questions peculiar to African societies, etc", "Applied issues: social political leadership and leadership behaviour, allegation problems in marriage and family life", "Religion and the problems of religious dogmatism in Nigeria, environmental pollution, etc"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 482', 'Military Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'second', 2, 'Vigilance, attention and signal detection. Personality and performance. Leadership. Obedience and compliance. Testing, selection, training and placement of military personnel. Combat stress, its nature and characteristics. Drug use among the military.', '["Vigilance, attention and signal detection. Personality and performance. Leadership", "Obedience and compliance", "Testing, selection, training and placement of military personnel", "Combat stress, its nature and characteristics. Drug use among the military"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 444', 'Sports Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'second', 2, 'The relevance of psychology in sports. The emotions and their arousal in sports settings. Individual/group motivation and sports performance. Reaction time in sport. Reactions to performance, propaganda, psychological immunization strategies. The role of imagery in sports. Treatment approaches to anxiety problems. Political dimension of international sports, Team versus individual games.', '["The relevance of psychology in sports. The emotions and their arousal in sports settings", "Individual/group motivation and sports performance. Reaction time in sport", "Reactions to performance, propaganda, psychological immunization strategies. The role of imagery in sports", "Treatment approaches to anxiety problems. Political dimension of international sports, Team versus individual games"]'::jsonb, 'Department of Psychology handbook'),
  ('PSY 492', 'Project', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '400 Level', 'second', 6, 'The student is required to conduct a psychological research under an assigned academic supervisor in the Department and submit an original report to the Department.', '["The student is required to conduct a psychological research under an assigned academic supervisor in the Department and submit an original report to the Department"]'::jsonb, 'Department of Psychology handbook'),
