  ('MAN 141', 'Elements of Business Economics', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '100 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('PHIL 101', 'Introduction to Philosophy', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '100 Level', 'first', 2, 'The nature and the principal branches of Philosophy: philosophical problems of other disciplines; introduction to African Philosophical Thought, Philosophical method; illustrations from the history of philosophy.', '["The nature and the principal branches of Philosophy", "Philosophical problems of other disciplines", "Introduction to African Philosophical Thought, Philosophical method", "Illustrations from the history of philosophy"]'::jsonb, 'Department of Philosophy handbook'),
  ('PSC 102', 'Introduction to Political Science II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '100 Level', 'second', 2, 'The course introduces students to the methods of Political Science, as well as the theory of knowledge; the relationship between political science and other disciplines.', '["The course introduces students to the methods of Political Science, as well as the theory of knowledge", "The relationship between political science and other disciplines"]'::jsonb, 'Department of Political Science handbook'),
  ('SOC 102', 'Introduction to Sociology II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '100 Level', 'second', 2, '', '[]'::jsonb, 'Faculty of Social Sciences course handbook'),
  ('GSP 102', 'Use of English II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Psychology', '100 Level', 'second', 2, 'Part A: Basic Grammar: Introduction. The concept of grammar and its place in language teaching and learning. Parts of speech and their functions (treated in detail). Closed and open class items in parts of speech, Nominalization, Grammatical Structures: the phrase, the clause and the sentence. Elementary Clause Analysis, Sentence Types, Elements and Patterns. Agreement (Grammatical agreement, Notional agreement, Proximity agreement) Agreement with the correlatives. Direct and Reported Speech, Error typology identification and correction.

Part B: Varieties of writing. Introduction (The Meaning, Nature and Purpose of Writing, Writing Types or Genres and their Characteristics). The paragraph as the basic unit of an essay (Types, Development of the Paragraph, Methods of Paragraph Development, The thesis statement). Point of view and style in writing. Qualities of a good piece of writing: Form, Diction and Content in writing. The Mechanics of Writing: punctuation, spelling and capitalization.

Part C: Writing Genres - Planning and choosing your theme. Deciding your genre. Choosing and developing your plot. Point of view, setting and characterization. Using the language that works. Essay Writing — Narration, Description, Exposition and Argumentation. Technical Writing: Letter Writing, Memorandum Writing, Speech Writing, Agenda and Minutes, own story for practice, Computer-linked writing, types, style, language, and process.', '["Part A: Basic Grammar - The concept of grammar, Parts of speech, Grammatical Structures, Sentence Types, Agreement, Direct and Reported Speech, Error typology", "Part B: Varieties of writing - Meaning, Nature and Purpose of Writing, the paragraph as the basic unit of an essay, the thesis statement, Qualities of a good piece of writing, Mechanics of Writing", "Part C: Writing Genres - Planning and choosing your theme, plot, point of view, setting and characterization", "Essay Writing - Narration, Description, Exposition and Argumentation", "Technical Writing - Letter Writing, Memorandum Writing, Speech Writing, Agenda and Minutes"]'::jsonb, 'Department of Mechanical Engineering handbook'),
